32:  const p=s.b[r][f];if(!p)return [];const out=[],add=(rr,ff,extra={})=>{if(inBounds(rr,ff))out.push({from:[r,f],to:[rr,ff],...extra});};
33:  if(p.t==='p'){const d=p.c==='w'?1:-1,start=p.c==='w'?1:6,promo=p.c==='w'?7:0;if(inBounds(r+d,f)&&!s.b[r+d][f]){add(r+d,f,r+d===promo?{promotion:'q'}:{});if(r===start&&!s.b[r+2*d][f])add(r+2*d,f,{double:true});}for(let df of [-1,1]){let rr=r+d,ff=f+df;if(inBounds(rr,ff)&&s.b[rr][ff]&&s.b[rr][ff].c!==p.c)add(rr,ff,rr===promo?{promotion:'q'}:{});if(s.ep&&same(s.ep,[rr,ff]))add(rr,ff,{ep:true});}}
