35:  else if('brq'.includes(p.t)){let dirs=[];if(p.t!=='b')dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(p.t!=='r')dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(let [dr,df] of dirs){let rr=r+dr,ff=f+df;while(inBounds(rr,ff)){if(!s.b[rr][ff])add(rr,ff);else{if(s.b[rr][ff].c!==p.c)add(rr,ff);break;}rr+=dr;ff+=df;}}}
