40:  if(p.t==='k'){n.castle[p.c==='w'?'K':'k']=false;n.castle[p.c==='w'?'Q':'q']=false;}if(p.t==='r'){if(r===0&&f===0)n.castle.Q=false;if(r===0&&f===7)n.castle.K=false;if(r===7&&f===0)n.castle.q=false;if(r===7&&f===7)n.castle.k=false;}if(target?.t==='r'){if(rr===0&&ff===0)n.castle.Q=false;if(rr===0&&ff===7)n.castle.K=false;if(rr===7&&ff===0)n.castle.q=false;if(rr===7&&ff===7)n.castle.k=false;}n.ep=m.double?[(r+rr)/2,f]:null;n.half=p.t==='p'||target||m.ep?0:n.half+1;if(s.turn==='b')n.full++;n.turn=s.turn==='w'?'b':'w';return n;}
